#[test]
fn all_public_client_methods_are_instrumented() -> Result<(), std::io::Error> {
    // Postcondition: tracing spans specified for all public operations.
    // Line-scan: every `pub fn` / `pub async fn` line must be preceded by a
    // `#[instrument` attribute (allowing doc comments / other attributes between).
    let checks: [(&str, &[&str]); 2] = [
        ("src/client.rs", &["new", "handle", "subscribe", "subscribe_account", "subscribe_raw_sip", "accounts", "call_state", "is_terminated", "shutdown"]),
        ("src/api/public_api_design.rs", &["register", "unregister", "set_registration_enabled", "registration_state", "make_call", "update_config"]),
    ];
    for (path, methods) in checks {
        let src = std::fs::read_to_string(path)?;
        for method in methods {
            let needle = format!("pub async fn {method}(");
            let line_idx = src.lines().position(|l| l.contains(&needle))
                .unwrap_or_else(|| panic!("{path} must define pub async fn {method}"));
            let context: Vec<&str> = src.lines().skip(line_idx.saturating_sub(6)).take(6).collect();
            assert!(
                context.iter().any(|l| l.contains("#[instrument")),
                "{path}: pub fn {method} must be preceded by #[instrument]; context: {context:?}"
            );
        }
    }
    Ok(())
}
